pre.code:
/* * Save hart id and dtb pointer. The thread pointer register is not * modified by C code. It is used by secondary_hart_loop. */ mv tp, a0 mv s1, a1
/* * Set the global data pointer to a known value in case we get a very * early trap. The global data pointer will be set its actual value only * after it has been initialized. */ mv gp, zero
/* * Set the trap handler. This must happen after initializing gp because * the handler may use it. */ la t0, trap_entry csrw MODE_PREFIX(tvec), t0
/* * Mask all interrupts. Interrupts are disabled globally (in m/sstatus) * for U-Boot, but we will need to read m/sip to determine if we get an * IPI */ csrw MODE_PREFIX(ie), zero
